# TFEL settings of Adastra (MI300A partition), sourced by build-tfel.sh,
# which defines P (root of the prototype). See
# deps/machines/workstation/tfel.sh for the variables to define.
#
# generic-parallel configurations: hip-hipcc (hipcc of ROCm, AMD platform;
# the libraries generated by MFront are compiled for the MI300A by
# HIPCC_COMPILE_FLAGS_APPEND, see machine.sh) and openmp-host-gcc. MFront
# compiles the code generated for the host with `-march=native`: TFEL,
# MGIS and mfem-mgis are built on a node of the partition mi300
# (deps/machines/adastra-mi300/jobs/build.slurm). The tests of TFEL are
# built only if PROTO_TFEL_TESTING=ON.
source "$P/scripts/env.sh"
BUILD=$PROTO_TFEL_BUILD
INSTALL=$PROTO_TFEL_INSTALL
CONFIGURATIONS="hip-hipcc;openmp-host-gcc"
TFEL_OPTIONS=(-DCMAKE_C_COMPILER="$PROTO_CC" -DCMAKE_CXX_COMPILER="$PROTO_CXX"
  -Denable-testing="${PROTO_TFEL_TESTING:-OFF}"
  -DTFEL_HIPCC_COMPILER="$ROCM_PATH/bin/hipcc" -DHIP_PLATFORM=amd)
